  const command = { command: process.execPath, args: ["--test", "calc.test.cjs"], timeoutMs: 10_000, cpuLimitSec: 5, maxOutputBytes: 65536, envAllowlist: [], namespaceJail: "required" as const, jailExecutable: join(root, "absent-helper") };
